CREATE OR REPLACE FUNCTION erp.propagate_conversion_hpp_for_po(p_po_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  r record;
  v_source_hpp numeric(18,6);
  v_desired numeric(18,6);
  v_current numeric(18,6);
  v_old_id uuid;
  v_new_id uuid;
